public class UsersDropdownProvider : IDropdownDataProvider<UserDto>
{
    public async Task<DropdownDataResult<UserDto>> GetItemsAsync(
        DropdownSearchRequest request, CancellationToken ct = default)
    {
        var result = await _api.SearchUsersAsync(
            request.SearchText, 
            request.Page, 
            request.PageSize, 
            ct);

        return DropdownDataResult<UserDto>.WithItems(
            result.Items, 
            result.TotalCount);
    }
}
